export function animateLogo(canvas, finish, signal) {

// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// SETUP
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const BASE_W = 808, BASE_H = 540;
const W = 1440, H = 810;

const ctx = canvas.getContext('2d');
const PIXEL_RATIO = Math.min(window.devicePixelRatio || 1, 2.5);
const SX = W / BASE_W;
const SY = H / BASE_H;
const S = Math.min(SX, SY);
const LOGO_SCALE = 0.84;
const LS = S * LOGO_SCALE;

canvas.width  = Math.round(W * PIXEL_RATIO);
canvas.height = Math.round(H * PIXEL_RATIO);
ctx.setTransform(PIXEL_RATIO, 0, 0, PIXEL_RATIO, 0, 0);
ctx.imageSmoothingEnabled = true;
ctx.imageSmoothingQuality = 'high';
resizeCanvasDisplay();
window.addEventListener('resize', resizeCanvasDisplay, {signal});

const ROSE    = '#b47b72'; 
const ROSE_DK = '#a97c6f'; 
const CREAM   = '#f8f0de'; 
const LOGO_CX = 410 * SX;
const CAKE_Y = 236 * SY;
const TITLE_Y = 330 * SY;
const SUBTITLE_Y = 388 * SY;
const GLOW_Y = 252 * SY;
const LEAF_FINAL_ANGLE = 0.45;
const leafSprite = new Image();
const titleSprite = new Image();
const processedTitleCanvas = document.createElement('canvas');
const processedTitleCtx = processedTitleCanvas.getContext('2d');
const leafReady = new Promise(resolve => {
  leafSprite.onload = resolve;
  leafSprite.onerror = resolve;
});
const titleReady = new Promise(resolve => {
  titleSprite.onload = () => {
    prepareTitleSprite();
    resolve();
  };
  titleSprite.onerror = resolve;
});
leafSprite.src = 'data:image/png;base64,';
titleSprite.src = 'data:image/png;base64,';

// Adjusted Timings for "Slow Smooth Faded" appearance
const T = {
  cakeFadeStart: 0.5,
  cakeFadeEnd:   3.0,
  textReveal:    1.5,
  textDone:      4.0,
  subFade:       3.5,
  leafStart:     4.0,
  leafLand:      6.5,
  total:         8.5
};

let startTime = null;
let raf = null;
signal.addEventListener('abort', () => cancelAnimationFrame(raf), {once:true});
Promise.all([leafReady, titleReady]).then(() => { if (canvas.isConnected && !signal.aborted) restart(); });

const ease = {
  inOut:    t => t<0.5 ? 2*t*t : -1+(4-2*t)*t,
  outSine:  t => Math.sin((t * Math.PI) / 2),
  outCubic: t => 1 - Math.pow(1 - t, 3),
};

const clamp = (v,a,b) => Math.max(a,Math.min(b,v));
const norm  = (t,a,b) => clamp((t-a)/(b-a),0,1);
const lerp  = (a,b,t) => a+(b-a)*t;

function sampleTitleBackground(imageData, width, height){
  const points = [
    [12, 12],
    [width - 13, 12],
    [12, height - 13],
    [width - 13, height - 13],
    [Math.floor(width * 0.5), 12],
    [Math.floor(width * 0.5), height - 13]
  ];
  let r = 0, g = 0, b = 0, count = 0;
  for (const [x, y] of points) {
    const ix = clamp(x, 0, width - 1);
    const iy = clamp(y, 0, height - 1);
    const idx = (iy * width + ix) * 4;
    r += imageData[idx];
    g += imageData[idx + 1];
    b += imageData[idx + 2];
    count++;
  }
  return { r: r / count, g: g / count, b: b / count };
}

function prepareTitleSprite(){
  if (!titleSprite.naturalWidth || !titleSprite.naturalHeight) return;

  const width = titleSprite.naturalWidth;
  const height = titleSprite.naturalHeight;
  processedTitleCanvas.width = width;
  processedTitleCanvas.height = height;
  processedTitleCtx.clearRect(0, 0, width, height);
  processedTitleCtx.drawImage(titleSprite, 0, 0, width, height);

  const image = processedTitleCtx.getImageData(0, 0, width, height);
  const data = image.data;
  const bg = sampleTitleBackground(data, width, height);

  for (let i = 0; i < data.length; i += 4) {
    const r = data[i];
    const g = data[i + 1];
    const b = data[i + 2];
    const a = data[i + 3];
    if (a === 0) continue;

    const dr = r - bg.r;
    const dg = g - bg.g;
    const db = b - bg.b;
    const distance = Math.sqrt(dr * dr + dg * dg + db * db);
    const brightness = (r + g + b) / 3;

    if (distance < 18 || (distance < 28 && brightness > 220)) {
      data[i + 3] = 0;
    } else if (distance < 42 && brightness > 190) {
      data[i + 3] = Math.round(a * ((distance - 18) / 24));
    }
  }

  processedTitleCtx.putImageData(image, 0, 0);
}

function resizeCanvasDisplay(){
  const viewportW = window.innerWidth;
  const viewportH = window.innerHeight;
  const sceneRatio = W / H;
  const viewportRatio = viewportW / viewportH;

  if (viewportRatio > sceneRatio) {
    canvas.style.width = viewportW + 'px';
    canvas.style.height = (viewportW / sceneRatio) + 'px';
  } else {
    canvas.style.width = (viewportH * sceneRatio) + 'px';
    canvas.style.height = viewportH + 'px';
  }
}

// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// DRAWING FUNCTIONS
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

function drawBackground(){
  ctx.fillStyle = CREAM;
  ctx.fillRect(0,0,W,H);

  const centerWarmth = ctx.createRadialGradient(W/2, H/2, 0, W/2, H/2, H * 0.72);
  centerWarmth.addColorStop(0, 'rgba(255,244,220,0.22)');
  centerWarmth.addColorStop(0.62, 'rgba(255,244,220,0.08)');
  centerWarmth.addColorStop(1, 'rgba(255,244,220,0)');
  ctx.fillStyle = centerWarmth;
  ctx.fillRect(0,0,W,H);

  for (let x = 0; x < W; x += 11) {
    const n = Math.sin(x * 0.17) + Math.sin(x * 0.043);
    ctx.globalAlpha = 0.006 + Math.abs(n) * 0.003;
    ctx.strokeStyle = n > 0 ? 'rgba(130,105,78,1)' : 'rgba(255,255,255,1)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x + Math.sin(x * 0.035) * 1.2, H);
    ctx.stroke();
  }

  for (let y = 0; y < H; y += 13) {
    const n = Math.sin(y * 0.19) + Math.sin(y * 0.052);
    ctx.globalAlpha = 0.005 + Math.abs(n) * 0.0025;
    ctx.fillStyle = n > 0 ? 'rgba(132,102,75,1)' : 'rgba(255,255,255,1)';
    ctx.fillRect(0, y, W, 1);
  }

  ctx.globalAlpha = 1;
  const edgeVignette = ctx.createRadialGradient(W/2, H/2, H * 0.28, W/2, H/2, H * 0.9);
  edgeVignette.addColorStop(0, 'rgba(180,123,114,0)');
  edgeVignette.addColorStop(1, 'rgba(180,123,114,0.025)');
  ctx.fillStyle = edgeVignette;
  ctx.fillRect(0,0,W,H);
  ctx.restore();
}

function drawCake(cx, cy, leafProgress, globalAlpha, elapsed){
  const s = LS; 
  ctx.save();
  ctx.globalAlpha = globalAlpha;
  
  // Bottom tier
  const bW=141*s, bH=56*s, bX=cx-bW/2, bY=cy-bH;
  roundRect(ctx, bX, bY, bW, bH, 5*s);
  ctx.fillStyle = ROSE;
  ctx.fill();
  drawFrostingWave(ctx, bX, bY+bH*0.42, bW, 2);

  // Top tier
  const tW=91*s, tH=52*s, tX=cx-tW/2, tY=bY-tH + 23*s;
  roundRect(ctx, tX, tY, tW, tH, 5*s);
  ctx.fill();
  drawFrostingWave(ctx, tX, tY+tH*0.43, tW, 2);

  // Leaf Spacing Integration:
  // In the reference, the leaf tip hovers slightly above the cake.
  // We offset the targetY to create that specific gap.
  const gap = 12 * LS; 
  drawFlowyLeaf(ctx, cx, tY - gap, leafProgress, elapsed);
  ctx.restore();
}

function drawFlowyLeaf(ctx, cx, targetY, t, elapsed) {
  if (t <= 0) return;
  ctx.save();
  const lW = 20 * LS, lH = 28 * LS;
  const yProgress = ease.inOut(t);
  const startY = targetY - 60 * LS; 
  let currY = lerp(startY, targetY, yProgress);
  
  // Ref-accurate tilt and landing
  const sway = Math.sin(t * Math.PI * 2) * 20 * LS * (1 - t);
  const settleP = ease.outCubic(norm(elapsed, T.leafLand, T.leafLand + 0.95));
  const settle = t >= 1 ? Math.sin(settleP * Math.PI) * 0.075 : 0;
  const angle = (Math.cos(t * Math.PI * 1.5) * 0.3 * (1 - t)) + LEAF_FINAL_ANGLE + settle; 

  ctx.globalAlpha = norm(t, 0, 0.3);
  ctx.translate(cx + sway, currY); 
  ctx.rotate(angle);

  if (leafSprite.complete && leafSprite.naturalWidth) {
    const spriteW = 41 * LS;
    const spriteH = 47 * LS;
    const anchorX = spriteW * 0.28;
    const anchorY = spriteH * 0.92;
    ctx.rotate(-LEAF_FINAL_ANGLE);
    ctx.drawImage(leafSprite, -anchorX, -anchorY, spriteW, spriteH);
  } else {
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(-lW*0.6, -lH*0.2, -lW*0.6, -lH*0.8, 0, -lH);
    ctx.bezierCurveTo( lW*0.6, -lH*0.8, lW*0.6, -lH*0.2, 0, 0);
    ctx.fillStyle = ROSE;
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(0, -lH*0.6);
    ctx.strokeStyle = CREAM; ctx.lineWidth = 1.8; ctx.stroke();
  }
  ctx.restore();
}

function drawFrostingWave(ctx, x, y, w, waves){
  ctx.save();
  ctx.beginPath();
  const seg = w / waves;
  ctx.moveTo(x, y);
  for(let i=0;i<waves;i++){
    const mx = x + i*seg + seg*0.5;
    const ex = x + (i+1)*seg;
    ctx.quadraticCurveTo(mx, y + 13, ex, y);
  }
  ctx.strokeStyle = CREAM;
  ctx.lineWidth = 3.5 * LS;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.stroke();
  ctx.restore();
}

function roundRect(ctx, x, y, w, h, r){
  ctx.beginPath();
  ctx.moveTo(x+r,y); ctx.lineTo(x+w-r,y);
  ctx.quadraticCurveTo(x+w,y,x+w,y+r); ctx.lineTo(x+w,y+h-r);
  ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h); ctx.lineTo(x+r,y+h);
  ctx.quadraticCurveTo(x,y+h,x,y+h-r); ctx.lineTo(x,y+r);
  ctx.quadraticCurveTo(x,y,x+r,y); ctx.closePath();
}

function drawText(elapsed){
  const cx = LOGO_CX;
  const ty = TITLE_Y;
  const titleAlpha = ease.outSine(norm(elapsed, T.textReveal, T.textDone));

  if (titleAlpha > 0 && processedTitleCanvas.width && processedTitleCanvas.height) {
    const titleH = 93 * LS;
    const titleW = titleH * (processedTitleCanvas.width / processedTitleCanvas.height) * 1.07;
    ctx.save();
    ctx.globalAlpha = titleAlpha;
    ctx.drawImage(processedTitleCanvas, cx - titleW / 2, ty - titleH * 0.705, titleW, titleH);
    ctx.restore();
  }

  // Subtitle
  const subAlpha = norm(elapsed, T.subFade, T.subFade + 1.5);
  if(subAlpha > 0){
    ctx.save();
    ctx.globalAlpha = subAlpha;
    ctx.font = `200 ${27 * LS}px "Avenir Next", "Helvetica Neue", "Gill Sans", Arial, sans-serif`;
    ctx.fillStyle = '#cba59b';
    drawTrackedText(ctx, 'HOMEMADE BAKERY', cx, SUBTITLE_Y, 13.4 * LS);
    ctx.restore();
  }
}

function measureTrackedText(ctx, text, tracking){
  let width = 0;
  for(let i=0;i<text.length;i++){
    width += ctx.measureText(text[i]).width;
    if(i < text.length - 1) width += tracking;
  }
  return width;
}

function drawTrackedText(ctx, text, x, y, tracking){
  let currX = x - measureTrackedText(ctx, text, tracking) / 2;
  for(let i=0;i<text.length;i++){
    const ch = text[i];
    ctx.fillText(ch, currX, y);
    currX += ctx.measureText(ch).width + tracking;
  }
}

function drawTrackedTextStaggered(ctx, text, x, y, tracking, elapsed){
  let currX = x - measureTrackedText(ctx, text, tracking) / 2;
  for(let i=0;i<text.length;i++){
    const ch = text[i];
    const charAlpha = ease.outSine(norm(elapsed, T.textReveal + i * 0.035, T.textDone));
    const prevAlpha = ctx.globalAlpha;
    ctx.globalAlpha = prevAlpha * charAlpha;
    ctx.fillText(ch, currX, y);
    ctx.globalAlpha = prevAlpha;
    currX += ctx.measureText(ch).width + tracking;
  }
}

function drawFinalWarmHold(elapsed){
  const inP = ease.outSine(norm(elapsed, 7.0, T.total));
  if (inP <= 0) return;

  ctx.save();
  const glow = ctx.createRadialGradient(LOGO_CX, GLOW_Y, 0, LOGO_CX, GLOW_Y, 165 * LS);
  glow.addColorStop(0, `rgba(255,198,122,${0.07 * inP})`);
  glow.addColorStop(0.45, `rgba(229,148,92,${0.035 * inP})`);
  glow.addColorStop(1, 'rgba(229,148,92,0)');
  ctx.fillStyle = glow;
  ctx.fillRect(0,0,W,H);
  ctx.restore();
}

// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// RENDER LOOP
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function render(ts){
  if(!startTime) startTime = ts;
  const elapsed = (ts - startTime) / 1000;
  drawBackground();
  drawFinalWarmHold(elapsed);

  // Slow Faded Entrance for Cake
  const cakeP = norm(elapsed, T.cakeFadeStart, T.cakeFadeEnd);
  const cakeEase = ease.outSine(cakeP);
  const cakeAlpha = cakeEase;
  const cakeY = CAKE_Y + (1 - cakeEase) * 4 * LS;
  const leafT = norm(elapsed, T.leafStart, T.leafLand);

  if(cakeAlpha > 0){
    drawCake(LOGO_CX, cakeY, leafT, cakeAlpha, elapsed);
  }

  drawText(elapsed);

  if(elapsed < T.total) raf = requestAnimationFrame(render);
  else finish();
}

function restart(){
  if(raf) cancelAnimationFrame(raf);
  startTime = null;
  raf = requestAnimationFrame(render);
}

}
